<script setup>
import { computed, ref } from 'vue'
import { Search } from '@lucide/vue'
import { useAirlineStore } from '../stores/airlineStore'
const { state } = useAirlineStore()
const selected = ref('All flights')
const filtered = computed(() => selected.value === 'All flights' ? state.flights : state.flights.filter((flight) => flight.status === selected.value))
</script>
<template><div class="page-enter"><div class="page-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> NETWORK CONTROL</div><h1>Flights</h1><p>Departure status and aircraft assignments across the network.</p></div><button class="button button-secondary" @click="selected = 'All flights'">{{ state.flights.length }} scheduled</button></div><section class="data-panel"><div class="toolbar-row"><span class="record-count">{{ filtered.length }} departures</span><div class="filter-group"><Search :size="14" /><select v-model="selected" aria-label="Filter flights"><option>All flights</option><option>On time</option><option>Boarding</option><option>Delayed</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Flight</th><th>Route</th><th>Departure</th><th>Gate</th><th>Aircraft</th><th>Passengers</th><th>Load</th><th>Status</th></tr></thead><tbody><tr v-for="flight in filtered" :key="flight.id"><td><b>{{ flight.id }}</b></td><td>{{ flight.origin }} <span class="route-arrow">→</span> {{ flight.destination }}</td><td>{{ flight.departure }} <small class="timezone">EDT</small></td><td><b>{{ flight.gate }}</b></td><td>{{ flight.aircraft }}</td><td>{{ flight.occupied }} <span class="muted-cell">/ {{ flight.capacity }}</span></td><td><div class="load-cell"><i><b :style="{ width: `${flight.occupied / flight.capacity * 100}%` }"></b></i>{{ Math.round(flight.occupied / flight.capacity * 100) }}%</div></td><td><span class="status-pill" :class="`status-${flight.status.toLowerCase().replaceAll(' ', '-')}`">{{ flight.status }}</span></td></tr></tbody></table></div></section></div></template>